// optimizeModel and getRig are pure and standalone; createModelCache(ctx) wires cloneModel onto
// ctx (ctx.prefabs caches the loaded/optimized prefab per name; see dist/game-context.js).
import * as T from 'three';
import {mergeGeometries} from 'three/addons/utils/BufferGeometryUtils.js';
import {CLASS_LIST} from './classes.js';
import {createPlayableCharacter} from './playable-characters.js';
export function optimizeModel(root){root.traverse(group=>{if(group.isMesh)return;const batches=new Map();for(const child of [...group.children]){if(!child.isMesh||Array.isArray(child.material)||child.children.length)continue;child.updateMatrix();let b=batches.get(child.material.uuid);if(!b){b={material:child.material,geometries:[]};batches.set(child.material.uuid,b);}const geometry=child.geometry.clone();geometry.applyMatrix4(child.matrix);if(!geometry.attributes.uv)geometry.setAttribute('uv',new T.BufferAttribute(new Float32Array(geometry.attributes.position.count*2),2));b.geometries.push(geometry.index?geometry.toNonIndexed():geometry);group.remove(child);}for(const b of batches.values()){const geometry=mergeGeometries(b.geometries);if(geometry)group.add(new T.Mesh(geometry,b.material));b.geometries.forEach(g=>g.dispose());}});}
export function getRig(root){const body=root.getObjectByName('body'),rig={root,body,baseY:body?.userData.baseY??body?.position.y,arms:[],legs:[]};root.traverse(o=>{if(o.name.startsWith('leg'))rig.legs.push(o);if(o.name.startsWith('arm'))rig.arms.push(o);});if(root.getObjectByName('ranger-quiver'))rig.rangerWeapons={bow:root.getObjectByName('weapon'),stowed:root.getObjectByName('ranger-stowed-bow'),right:root.getObjectByName('ranger-knife-right'),left:root.getObjectByName('ranger-knife-left'),sheathed:root.getObjectByName('ranger-sheathed-knives')};if(root.getObjectByName('oathkeeper-wing-harness'))rig.oathkeeper={wings:[root.getObjectByName('oathkeeper-wing-left'),root.getObjectByName('oathkeeper-wing-right')],blaster:root.getObjectByName('oathkeeper-blaster'),holster:root.getObjectByName('oathkeeper-holstered-blaster')};return rig;}
export function createModelCache(ctx){
 function cloneModel(name){if(!ctx.prefabs[name]){const definition=CLASS_LIST.find(c=>c.concept===name);ctx.prefabs[name]=createPlayableCharacter(definition?.id||'sorcerer',name);optimizeModel(ctx.prefabs[name]);}const model=ctx.prefabs[name].clone(true),materials=new Map();model.traverse(o=>{if(!o.isMesh)return;o.castShadow=true;o.receiveShadow=true;const cloneMaterial=source=>{if(!materials.has(source.uuid)){const m=source.clone();m.userData.baseEmissive=m.emissive.clone();materials.set(source.uuid,m);}return materials.get(source.uuid);};o.material=Array.isArray(o.material)?o.material.map(cloneMaterial):cloneMaterial(o.material);});return model;}
 return {cloneModel};
}
